SET NAMES utf8mb4;
UPDATE `level` SET `map_data` = '{"version":3,"level_name":"Сердце леса","description":"Лесной босс Древень запер дверь. Собери настоящий ключ среди фальшивок, выстрели ракетой и выйди. Босс хитрый: после находки ключа он переставит выход.","hint":"Ключи: один настоящий и четыре фальшивки, каждый запуск они лежат по-новому. Босс подскажет, в какой стороне настоящий. Собери его, встань на линию с боссом и запусти ракету: robot.attack(5). После попадания босс бьёт по твоей клетке - уходи.","biome":"forest","width":15,"height":15,"entrance":"A1","entrance_direction":"right","exit":"O15","alternate_exit":"O1","rocks":["B3","D5","F3","G11","J3","K6","L10","M4","N12","E13","J13","K11","B12","B9","N6","F12","H12"],"walls":[],"terrain":{},"coins":[{"id":1,"position":"F1"},{"id":2,"position":"H1"},{"id":3,"position":"K15"},{"id":4,"position":"N11"}],"keys":[{"id":1,"position":"C3","fake":false},{"id":2,"position":"E5","fake":true},{"id":3,"position":"J4","fake":true},{"id":4,"position":"M10","fake":true},{"id":5,"position":"D13","fake":true}],"required_key_position":"C3","enemies":[{"id":1,"type":"golem","position":"H8","patrol":["H8"],"move_every":3,"boss":true,"hp":3}],"boss":{"name":"Древень","title":"Хранитель леса","avatar":"forest","hp":3,"player_hp":3,"attack_range":6,"cooldown":2,"fake_key_damage":1,"ability":"Путает тропы: после находки настоящего ключа меняет выход местами. Отвечает залпом в клетку, откуда стреляли.","intro":["Я Древень, хранитель этого леса.","Ты робот? Забавно. Давно ко мне не заходили гости.","Дверь заперта. Открою её только тому, кто победит меня в честном бою.","Смотри: я разбросал по поляне пять ключей. Настоящий только один.","Собери его, не трогай фальшивки и выстрели в меня ракетой. Начнём!","И ещё: после твоего попадания я бью по клетке, откуда стрелял. Не стой на месте!"],"key_line":"Настоящий ключ у тебя. Но дверь откроется только после боя!","fake_key_line":"Фальшивка! Минус одна жизнь. Внимательнее.","hit_line":"Метко! Но я ещё держусь.","defeat_line":"Ха! Ты сильнее, чем кажешься. Дверь открыта - я переставил её наверх, не сердись.","player_defeat_line":"Ты потерял все жизни. Лес начинает бой заново!","shot_damage":2,"charge_line":"Я отвечаю залпом! Уходи с клетки, иначе получишь ракету.","shot_line":"Попадание! В лесу нельзя стоять на месте.","miss_line":"Мимо! Ты успел отойти.","key_hint_line":"Мой настоящий ключ лежит {direction} меня. Остальные ключи - ловушки."},"three_star_runs":6}' WHERE `level_id` = 6;
UPDATE `level` SET `map_data` = '{"version":3,"level_name":"Пески под солнцем","description":"Скорпион-хан вызывает робота на бой. На карте пять ключей, но четыре фальшивки отнимают по две жизни. Найди настоящий ключ и пробей панцирь ракетой.","hint":"Настоящий ключ подскажет босс. Фальшивки отнимают 2 HP. Встань на линию с боссом и стреляй: robot.attack(5). После попадания уходи с клетки, иначе босс ответит залпом.","biome":"desert","width":15,"height":15,"entrance":"A1","entrance_direction":"right","exit":"O15","rocks":["B4","D3","F6","G3","J6","K3","L6","M10","N4","B10","E11","H12","K12","B12","F10","J12","M13"],"walls":[],"terrain":{},"coins":[{"id":1,"position":"F1"},{"id":2,"position":"H1"},{"id":3,"position":"K15"},{"id":4,"position":"N11"}],"keys":[{"id":1,"position":"C3","fake":false},{"id":2,"position":"E5","fake":true},{"id":3,"position":"J4","fake":true},{"id":4,"position":"M12","fake":true},{"id":5,"position":"D13","fake":true}],"required_key_position":"C3","enemies":[{"id":1,"type":"scorpion","position":"H8","patrol":["H8"],"move_every":3,"boss":true,"hp":4}],"boss":{"name":"Скорпион-хан","title":"Песчаный владыка","avatar":"desert","hp":4,"player_hp":3,"attack_range":6,"cooldown":2,"fake_key_damage":2,"ability":"Песчаная буря: фальшивые ключи отнимают 2 жизни. После попадания отвечает залпом в твою клетку.","intro":["Я Скорпион-хан, гроза этих песков.","Мой панцирь не пробить обычной атакой. Сначала найди настоящий ключ.","Ключей пять, но четыре из них - песчаные обманки. Каждая отнимет две жизни.","Собери настоящий ключ, прицелься и запусти ракету. Посмотрим, кто сильнее.","Попал в меня - и я бью туда же. Не задерживайся на клетке!"],"key_line":"Настоящий ключ? Неплохо. Но дверь всё ещё моя.","fake_key_line":"Обманка! Песчаная буря выпивает две жизни.","hit_line":"Ты попал?! Песок не защитил меня.","defeat_line":"Достойный выстрел. Забирай выход, путник.","player_defeat_line":"Пески поглотили тебя. Начинаем заново!","shot_damage":2,"charge_line":"Песчаная буря наводится на твою клетку!","shot_line":"Буря накрыла тебя! Минус жизнь.","miss_line":"Ветер унёс бурю в сторону - ты ушёл.","key_hint_line":"Настоящий ключ зарыт {direction} меня. Песок скрыл остальные."},"three_star_runs":6}' WHERE `level_id` = 12;
UPDATE `level` SET `map_data` = '{"version":3,"level_name":"Трон вечной зимы","description":"Ледяная королева заморозила дверь. Настоящий ключ один, остальные - ледяные ловушки. Перезарядка ракеты длится дольше обычного.","hint":"Настоящий ключ подскажет босс. Босс на H8. Между выстрелами - 3 действия: перезарядка и уход с клетки. Стреляй: robot.attack(5).","biome":"snow","width":15,"height":15,"entrance":"A1","entrance_direction":"right","exit":"O15","rocks":["B3","D6","F4","G10","J4","K7","L11","M3","N13","E9","H11","K13","B11","F13","J10","M11","N5"],"walls":[],"terrain":{},"coins":[{"id":1,"position":"F1"},{"id":2,"position":"H1"},{"id":3,"position":"K15"},{"id":4,"position":"N11"}],"keys":[{"id":1,"position":"C3","fake":false},{"id":2,"position":"E5","fake":true},{"id":3,"position":"J6","fake":true},{"id":4,"position":"M10","fake":true},{"id":5,"position":"D13","fake":true}],"required_key_position":"C3","enemies":[{"id":1,"type":"snowman","position":"H8","patrol":["H8"],"move_every":3,"boss":true,"hp":3}],"boss":{"name":"Ледяная королева","title":"Хозяйка вечной зимы","avatar":"snow","hp":3,"player_hp":3,"attack_range":6,"cooldown":3,"fake_key_damage":1,"ability":"Вечная мерзлота: перезарядка ракеты дольше - 3 действия. После попадания бьёт по твоей клетке.","intro":["Я Ледяная королева. Здесь всё замерзает, даже время.","Пять ключей лежат на снегу. Настоящий один, остальные - ловушки.","Мои чары замедляют перезарядку. Три действия между выстрелами.","Найди ключ, выжди перезарядку и стреляй. Докажи, что не замёрз.","Я отвечаю залпом в клетку, откуда ты стрелял. Уходи сразу."],"key_line":"Ключ у тебя. Лёд треснул, но дверь ещё заперта.","fake_key_line":"Ловушка! Мороз отнимает жизнь.","hit_line":"Трещина в моей броне! Ещё выстрел.","defeat_line":"Ты растопил мой трон. Проходи, герой.","player_defeat_line":"Холод победил. Бой начинается с начала.","shot_damage":2,"charge_line":"Лёд под тобой трещит - я целюсь!","shot_line":"Сосулька пробила броню! Минус жизнь.","miss_line":"Сосулька вонзилась в снег - ты сменил клетку.","key_hint_line":"Настоящий ключ замёрз {direction} меня. Прочие - ледяные обманки."},"three_star_runs":6}' WHERE `level_id` = 18;
UPDATE `level` SET `map_data` = '{"version":3,"level_name":"Сердце вулкана","description":"Магмовый титан поднялся из жерла. Его броня выдержит пять ракет. Найди настоящий ключ среди обманок и не подходи к боссу вплотную.","hint":"Настоящий ключ подскажет босс. У босса 5 HP, дальность ракеты - до 7 клеток. После попадания босс бьёт по твоей клетке - уходи. Стреляй: robot.attack(5).","biome":"volcano","width":15,"height":15,"entrance":"A1","entrance_direction":"right","exit":"O15","rocks":["B5","D4","F5","G4","J5","K4","L9","M5","N10","E12","H13","K10","B13","F11","J11","M12","N7"],"walls":[],"terrain":{},"coins":[{"id":1,"position":"F1"},{"id":2,"position":"H1"},{"id":3,"position":"K15"},{"id":4,"position":"N11"}],"keys":[{"id":1,"position":"C3","fake":false},{"id":2,"position":"E5","fake":true},{"id":3,"position":"J4","fake":true},{"id":4,"position":"M10","fake":true},{"id":5,"position":"D13","fake":true}],"required_key_position":"C3","enemies":[{"id":1,"type":"golem","position":"H8","patrol":["H8"],"move_every":3,"boss":true,"hp":5}],"boss":{"name":"Магмовый титан","title":"Сердце вулкана","avatar":"volcano","hp":5,"player_hp":3,"attack_range":7,"cooldown":2,"fake_key_damage":1,"ability":"Лавовый панцирь: у босса 5 жизней. После попадания отвечает залпом в твою клетку.","intro":["Я Магмовый титан, сердце этого вулкана.","Моя броня крепка: пять попаданий, не меньше.","Пять ключей спрятаны среди камней. Настоящий только один.","Найди его, перезаряди ракету и стреляй. Только не подходи слишком близко.","Попадание по мне - и я бью в ответ по твоей клетке. Успей уйти!"],"key_line":"Ключ найден. Но дверь откроется лишь после боя.","fake_key_line":"Обманка! Лава обжигает - минус жизнь.","hit_line":"Искры летят! Но я ещё стою.","defeat_line":"Моя магма остыла. Выход открыт.","player_defeat_line":"Лава забрала тебя. Начнём заново!","shot_damage":1,"charge_line":"Лава наводится на твою клетку!","shot_line":"Лавовый залп попал! Минус жизнь.","miss_line":"Лава прожгла пол там, где ты стоял. Ушёл.","key_hint_line":"Настоящий ключ раскалён {direction} меня. Остальные - пепел."},"three_star_runs":6}' WHERE `level_id` = 24;
